module parallel2serial (
    input clk, 
    input rst_n, 
    input [3:0] d, 
    output valid_out, 
    output dout
);
// Internal signals declaration
reg [3:0] data;
reg [1:0] cnt;
reg valid;
// Combinational logic for dout
assign dout = data[3];
// Sequential logic for valid_out and data
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        cnt <= 0;
        valid <= 0;
        data <= 0;
    end else begin
        cnt <= cnt + 1;
        valid <= 0;
        data <= {data[2:0], 1'b0};
        if (cnt == 3) begin
            data <= d;
            cnt <= 0;
            valid <= 1;
        end
    end
end
// Assign valid_out to valid
assign valid_out = valid;
endmodule
